/// 功能：将内存中缓冲区中的数据写入文件。
/// 参数：fd 表示待写入文件的文件描述符；
///      buf 表示内存中缓冲区的起始地址；
///      len 表示内存中缓冲区的长度。
/// 返回值：返回成功写入的长度。
/// syscall ID：64
fn syswrite(fd: usize, buf: const u8, len: usize) - isize;

/// 功能：退出应用程序并将返回值告知批处理系统。
/// 参数：xstate 表示应用程序的返回值。
/// 返回值：该系统调用不应该返回。
/// syscall ID：93
fn sysexit(xstate: usize) - !;

系统调用参数传递

 rust
fn syscall(id: usize, args: [usize; 3]) - isize {
    let mut ret: isize;
    unsafe {
        asm!(
            "ecall",
            inlateout("x10") args[0] = ret, //第一个参数&返回值
            in("x11") args[1],               //第二个参数
            in("x12") args[2],               //第三个参数
            in("x17") id                     //syscall编号
        );
    }
    ret //返回值
}
参考文档：Rust by Example - Inline assembly

系统调用封装
const SYSCALLWRITE: usize = 64; 
const SYSCALLEXIT: usize = 93;
//对系统调用的封装
pub fn syswrite(fd: usize, buffer: &[u8]) - isize {
    syscall(SYSCALLWRITE, [fd, buffer.asptr() as usize, buffer.len()])
}
pub fn sysexit(xstate: i32) - isize {
    syscall(SYSCALLEXIT, [xstate as usize, 0, 0])
}

