unsafe fn loadapp(&self, appid: usize) {
    // clear icache
    asm!("fence.i");
    // clear app area
    ...
    let appsrc = core::slice::fromrawparts(
        self.appstart[appid] as const u8,
        self.appstart[appid + 1] - self.appstart[appid] );
    let appdst = core::slice::fromrawpartsmut(
        APPBASEADDRESS as mut u8,
        appsrc.len() );
    appdst.copyfromslice(appsrc);
}

